-- 0059 — owner follow-up 2026-10-14: book any Metro Detroit ZIP; gear actually owned; buy-on-demand items.
-- Zone 2 ($35) = every ZIP code in Wayne, Oakland and Macomb counties (2020 Census ZCTA-county file, ZIPs with at least 25% of their
-- land in the three counties, plus 48112 Belleville PO boxes) that is not in Zone 1. No city list any more: the whole metro area is bookable.
alter table public.rental_addons add column if not exists buy_on_demand boolean not null default false;   -- bought for the booking, not stocked

update public.rental_settings set zones = '[{"name": "Zone 1", "fee": 10, "label": "Lincoln Park, Allen Park, Southgate, Wyandotte, Ecorse, River Rouge, Melvindale, Taylor, Dearborn, Dearborn Heights, Riverview, Trenton, Grosse Ile, Romulus, Southwest and downtown Detroit", "zips": ["48146", "48101", "48195", "48192", "48229", "48122", "48180", "48209", "48217", "48210", "48216", "48218", "48120", "48124", "48126", "48128", "48125", "48127", "48193", "48183", "48138", "48174", "48201", "48202", "48207", "48208", "48226", "48243"]}, {"name": "Zone 2", "fee": 35, "label": "Everywhere else in Metro Detroit (Wayne, Oakland and Macomb counties), including Farmington Hills, Bloomfield Township, Redford, Ferndale, the Grosse Pointes, Westland, Brownstown, Woodhaven, Flat Rock and Belleville", "zips": ["48005", "48009", "48015", "48017", "48021", "48025", "48026", "48030", "48033", "48034", "48035", "48036", "48038", "48042", "48043", "48044", "48045", "48047", "48048", "48050", "48051", "48062", "48065", "48066", "48067", "48069", "48070", "48071", "48072", "48073", "48075", "48076", "48080", "48081", "48082", "48083", "48084", "48085", "48088", "48089", "48091", "48092", "48093", "48094", "48095", "48096", "48098", "48111", "48112", "48134", "48135", "48141", "48150", "48152", "48154", "48164", "48165", "48167", "48168", "48170", "48173", "48178", "48184", "48185", "48186", "48187", "48188", "48203", "48204", "48205", "48206", "48211", "48212", "48213", "48214", "48215", "48219", "48220", "48221", "48223", "48224", "48225", "48227", "48228", "48230", "48233", "48234", "48235", "48236", "48237", "48238", "48239", "48240", "48242", "48301", "48302", "48304", "48306", "48307", "48309", "48310", "48312", "48313", "48314", "48315", "48316", "48317", "48320", "48322", "48323", "48324", "48326", "48327", "48328", "48329", "48331", "48334", "48335", "48336", "48340", "48341", "48342", "48346", "48348", "48350", "48356", "48357", "48359", "48360", "48362", "48363", "48367", "48370", "48371", "48374", "48375", "48377", "48380", "48381", "48382", "48383", "48386", "48390", "48393", "48442", "48462"]}]'::jsonb where id;

-- furniture dolly: offered without stock, bought when someone books one; supplies are bought for each booking too
update public.rental_addons set requires = '{}'::jsonb, buy_on_demand = true where asset_type = 'furniture_dolly' and kind = 'rent';
update public.rental_addons set buy_on_demand = true where kind = 'sell';

-- gear owned today: 2 standard hand trucks, 1 convertible, no furniture dolly yet (rows kept, retired)
update public.rental_assets set status = 'retired', condition_notes = trim(coalesce(condition_notes, '') || ' Retired 2026-10-14: not owned.')
where asset_tag in ('H-03', 'H-04', 'F-01', 'F-02') and status = 'available';

select (select jsonb_agg(z->>'name' || ' $' || (z->>'fee') || ' ' || jsonb_array_length(z->'zips') || ' zips') from public.rental_settings s, jsonb_array_elements(s.zones) z) as zones,
       (select jsonb_object_agg(asset_type || ':' || status, n) from (select asset_type, status, count(*) n from public.rental_assets where asset_type <> 'tote' group by 1, 2) x) as gear,
       (select jsonb_agg(name order by sort_order) from public.rental_addons where active and buy_on_demand) as buy_on_demand;
